"""Validation for generated BYO Blob authentication models."""

from azure.containerapps.sandbox.models import AzureBlobByoManagedIdentityAuth


def _validate_byo_blob_auth(auth: AzureBlobByoManagedIdentityAuth) -> None:
    if auth.kind != "ManagedIdentity":
        raise ValueError("BYO blob auth kind must be 'ManagedIdentity'")
    identity = auth.identity
    if identity is None:
        raise ValueError("BYO blob auth identity must not be None")
    if identity.kind not in ("SystemAssigned", "UserAssigned"):
        raise ValueError("identity selector kind must be 'SystemAssigned' or 'UserAssigned'")
    resource_id = identity.get("resourceId")
    if identity.kind == "UserAssigned" and not resource_id:
        raise ValueError("identity selector resource_id is required when kind is 'UserAssigned'")
    if identity.kind == "SystemAssigned" and resource_id:
        raise ValueError("identity selector resource_id must not be set when kind is 'SystemAssigned'")
